A = (6^2/10,6*8/10);
B = (0,0);
C = (10,0);
G = (6^2/10,0);
X = (0,-10);
Y = (10,-10);
F = extension(A,Y,B,C);
D = extension(F,F + A - G,A,C);
E = extension(D,D + B - C,A,B);
H = E + F - D;

draw(A--B--C--cycle);
draw(H--E--D--F);
draw(A--G);

